import{_ as o,C as a,c as s,o as n,ag as e,j as r,G as l}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"Registration Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings-and-customization/registration-settings.md","filePath":"guide/settings-and-customization/registration-settings.md","lastUpdated":1752494831000}'),g={name:"guide/settings-and-customization/registration-settings.md"};function d(h,t,u,p,c,f){const i=a("ZoomableImage");return n(),s("div",null,[t[0]||(t[0]=e('<h1 id="registration-settings" tabindex="-1">Registration Settings <a class="header-anchor" href="#registration-settings" aria-label="Permalink to &quot;Registration Settings&quot;">​</a></h1><p>The Registration Settings section gives you complete control over your affiliate registration form. You can enable or disable registrations, set approval requirements, and customize the form fields to collect the information you need from new affiliates.</p><h3 id="accessing-registration-settings" tabindex="-1">Accessing Registration Settings <a class="header-anchor" href="#accessing-registration-settings" aria-label="Permalink to &quot;Accessing Registration Settings&quot;">​</a></h3><p>To configure these options, navigate from your WordPress dashboard to <strong>FluentAffiliate → Settings → Registration Settings</strong>.</p><h3 id="general-registration-options" tabindex="-1">General Registration Options <a class="header-anchor" href="#general-registration-options" aria-label="Permalink to &quot;General Registration Options&quot;">​</a></h3><p>At the top of the page, you will find the two primary settings that control your entire affiliate registration process.</p><ul><li><p><strong>Enable Affiliate Registration:</strong> This acts as the master switch for your affiliate program&#39;s public registration.</p><ul><li>When this option is <strong>enabled</strong>, the affiliate registration form will be active and accessible, allowing new users to sign up.</li><li>If you <strong>disable</strong> this option, it will prevent any new users from registering as affiliates.</li></ul></li><li><p><strong>Require admin approval for new affiliates:</strong> This setting gives you direct control over your affiliate vetting and approval workflow.</p><ul><li><strong>When Enabled (Manual Approval):</strong> If you check this box, you have full control over who joins your program. New applicants will have their status set to &quot;pending.&quot; You will then need to navigate to their individual affiliate profile to manually review their application and approve them. This is the recommended setting if you want to screen your affiliates before they can start promoting your site.</li><li><strong>When Disabled (Automatic Approval):</strong> If you leave this box unchecked, the approval process is hands-off. Any user who successfully completes the registration form will instantly become an active affiliate and can begin generating referral links immediately.</li></ul></li></ul>',7)),r("p",null,[l(i,{src:"/guide/public/images/settings-and-customization/registration-settings/registration-settings.webp",alt:"Registration Settings"})]),t[1]||(t[1]=e('<h3 id="managing-registration-fields" tabindex="-1">Managing Registration Fields <a class="header-anchor" href="#managing-registration-fields" aria-label="Permalink to &quot;Managing Registration Fields&quot;">​</a></h3><p>This section allows you to customize the registration form that potential affiliates will fill out. You can enable, disable, and edit the fields as needed.</p><h4 id="activating-or-hiding-fields" tabindex="-1">Activating or Hiding Fields <a class="header-anchor" href="#activating-or-hiding-fields" aria-label="Permalink to &quot;Activating or Hiding Fields&quot;">​</a></h4><p>For many fields, such as &quot;How will you promote us?&quot; or &quot;Website URL,&quot; you can simply click the toggle switch to activate (show) or hide the field on the registration form.</p><h4 id="editing-fields" tabindex="-1">Editing Fields <a class="header-anchor" href="#editing-fields" aria-label="Permalink to &quot;Editing Fields&quot;">​</a></h4><p>For core system fields like &quot;Full name&quot; or &quot;Email Address,&quot; you can click the <strong>Edit</strong> button to modify their properties. This will open the <strong>Edit Registration Field</strong> pop-up.</p><p>In this pop-up, you can modify the following options:</p><ul><li><strong>Label:</strong> Change the display name of the field.</li><li><strong>Placeholder:</strong> Set the placeholder text that appears inside the input field.</li><li><strong>Required:</strong> Choose whether the field is mandatory for the user to fill out.</li><li><strong>Status:</strong> Use this toggle to enable or disable the field on the form.</li></ul><p>As noted in the pop-up, some system-defined fields may have limitations, such as only allowing label edits.</p><p>After making your customizations, remember to click the <strong>Save Settings</strong> button at the bottom of the page to apply all changes.</p>',10))])}const y=o(g,[["render",d]]);export{b as __pageData,y as default};
